fn frame(t: i32) {
    let tab = [0, 25, 49, 71, 90, 106, 117, 124, 127, 124, 117, 106, 90, 71, 49, 25, 0, -25, -49, -71, -90, -106, -117, -124, -127, -124, -117, -106, -90, -71, -49, -25];
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let cx: i32 = w / 2 + tab[(t / 4) & 31] * 70 / 127;
    let cy: i32 = h / 2 + tab[((t / 4) + 8) & 31] * 55 / 127;
    let cell: i32 = 16;
    let cols: i32 = w / cell;
    let rows: i32 = h / cell;
    host::display::clear(0x0a0a14);
    let mut by: i32 = 0;
    while by < rows {
        let mut bx: i32 = 0;
        while bx < cols {
            let x: i32 = bx * cell + cell / 2;
            let y: i32 = by * cell + cell / 2;
            let d2: i32 = (x - cx) * (x - cx) + (y - cy) * (y - cy);
            let mut dk: i32 = d2 / 2000;
            if dk > 15 { dk = 15; }
            let s: i32 = 15 - dk;
            if s > 0 {
                host::display::fill_rect(x - s / 2, y - s / 2, s, s, 0xffcf7a);
            }
            bx = bx + 1;
        }
        by = by + 1;
    }
    host::display::present();
}
